// v4: Extended to capture optional topic hint after /generate command
// Usage: /generate            → fully random
// Usage: /generate sss 2025   → hint steers content angle
const body = $input.first().json.body || $input.first().json;

let updateType = 'unknown';
let chatId = 'YOUR_TELEGRAM_CHAT_ID';
let messageText = '';
let callbackData = '';
let callbackQueryId = '';
let messageId = '';
let username = '';
let topicHint = '';

if (body.message) {
  updateType = 'message';
  chatId = String(body.message.chat.id);
  messageText = body.message.text || '';
  messageId = String(body.message.message_id || '');
  username = body.message.from?.username || body.message.from?.first_name || 'User';
} else if (body.callback_query) {
  updateType = 'callback_query';
  chatId = String(body.callback_query.message.chat.id);
  callbackData = body.callback_query.data || '';
  callbackQueryId = String(body.callback_query.id);
  messageId = String(body.callback_query.message.message_id || '');
  username = body.callback_query.from?.username || body.callback_query.from?.first_name || 'User';
}

const isGenerate = updateType === 'message' && messageText.trim().startsWith('/generate');

// Extract optional hint text after /generate (e.g. "/generate BIR compliance" → "BIR compliance")
if (isGenerate && messageText.trim().length > 9) {
  topicHint = messageText.trim().slice(9).trim();
}

return [{
  json: {
    updateType, chatId, messageText, callbackData, callbackQueryId, messageId, username,
    isGenerate,
    isCallback: updateType === 'callback_query',
    topicHint
  }
}];

