return [{ json: { filename: img.filename, subfolder: img.subfolder || '', imageType: img.type || 'output', promptId, chatId: $('Extract Prompt ID').first().json.chatId, topic: $('Extract Prompt ID').first().json.topic, caption: $('Extract Prompt ID').first().json.caption, hashtags: $('Extract Prompt ID').first().json.hashtags } }];

const igData = $input.first().json;
const prevData = $('Extract IG Result').first().json;

const igPermalink = igData.permalink || `https://www.instagram.com/p/${prevData.igMediaId}/`;

return [{
  json: {
    chatId: prevData.chatId,
    topic: prevData.topic,
    fbPostUrl: prevData.fbPostUrl,
    igPostUrl: igPermalink,
    igPosted: true
  }
}];

// v5.8: The "No-Fail" Llama 3 JSON Parser
const response = $input.first().json;

// 1. Extract raw text from the textResponse field
let rawText = (response.textResponse || response.text || "").trim();

// 2. Safely get Chat ID
const parseUpdateNode = $("Parse Update").first().json;
const chatId = parseUpdateNode.chatId;

if (!rawText) throw new Error('Empty response from AnythingLLM');

// 3. CRITICAL CLEANING: Standardize all whitespace variants
// This removes non-breaking spaces and other invisible characters that cause indexOf/JSON.parse to fail
rawText = rawText.replace(/[\u00A0\u1680​\u180e\u2000-\u200a\u2028\u2029\u202f\u205f​\u3000]/g, " ");

// 4. EXTRACTION: Find the JSON boundaries
// We look for the first '{' and the last '}' to strip any Llama preamble or "Note:" footers
const startBrace = rawText.indexOf('{');
const endBrace = rawText.lastIndexOf('}');

if (startBrace === -1 || endBrace === -1) {
    throw new Error('No JSON found in LLM response.');
}

let jsonString = rawText.substring(startBrace, endBrace + 1);

let parsed = null;
try {
    // Attempt 1: Standard Parse
    parsed = JSON.parse(jsonString);
} catch (e) {
    try {
        // Attempt 2: Escape literal newlines within the string
        // This fixes the "Unexpected token" error caused by real line breaks inside quotes
        const escapedJson = jsonString.replace(/\n/g, "\\n").replace(/\r/g, "\\r");
        parsed = JSON.parse(escapedJson);
    } catch (err) {
        // Attempt 3: Regex Fallback (The "Indestructible" Method)
        // If the LLM mangles the quotes or adds commentary, we just grab the text between the keys
        const extract = (key) => {
            const regex = new RegExp(`"${key}"\\s*:\\s*"(.*?)"`, "s");
            const match = jsonString.match(regex);
            return match ? match[1] : "";
        };

        parsed = {
            topic: extract("topic"),
            caption: extract("caption"),
            hashtags: extract("hashtags")
        };
    }
}

// 5. DATA PREPARATION & CLEANUP
// Remove any accidental literal "\n" characters the LLM might have typed out
const cleanText = (str) => (str || "").replace(/\\n/g, "\n").trim();

const topic = cleanText(parsed.topic || "CubicPayroll Update");
const fullCaption = cleanText(parsed.caption || "");
const hashtags = cleanText(parsed.hashtags || "");

// 6. TELEGRAM SIZE GUARD (1024 chars for images with captions)
const overhead = topic.length + hashtags.length + 50; 
const telegramLimit = 1024 - overhead;

let telegramCaption = fullCaption;
if (fullCaption.length > telegramLimit) {
    const tempCut = fullCaption.substring(0, telegramLimit);
    const lastPeriod = tempCut.lastIndexOf('.');
    telegramCaption = lastPeriod > 0 ? tempCut.substring(0, lastPeriod + 1) : tempCut + "...";
}

return [{
    json: {
        chatId: chatId,
        topic: topic,
        hashtags: hashtags,
        tg_caption: telegramCaption,
        full_caption: fullCaption,
        caption: telegramCaption
    }
}];

